\"\"\"Minimal OpenAI Responses API client using only the Python standard library.

This module sends text prompts to OpenAI's Responses API
("'``POST https://api.openai.com/v1/responses``) without third-party
dependencies. Prompt text is treated as private: it is never logged or written
anywhere by this module.

Typical use::

    from openai_client import OpenAIClient

    client = OpenAIClient()  # reads OPENAI_API_KEY from the environment
    print(client.ask("Summarize the theory of relativity in two sentences."))

Or from the command line::

    export OPENAI_API_KEY="sk-..."
    python openai_client.py "Hello!"
    echo "Hello!" | python openai_client.py
"""

from __future__ import annotations

import json
import os
import sys
import urllib.error
import urllib.request
from typing import Any, Dict, Iterable, List, Optional

__all__ = ["OpenAIClient", "OpenAIError", "ask"]

DEFAULT_BASE_URL = "https://api.openai.com/v1"
DEFAULT_MODEL = "gpt-4o-mini"
DEFAULT_TIMEOUT = 60.0


class OpenAIError(RuntimeError):
    """Raised when the API request fails.

    The message intentionally excludes the prompt and the API key. When the
    server provides one, the OpenAI request id is included to aid support.
    """

    def __init__(self, message: str, *, status: Optional[int] = None,
                 request_id: Optional[str] = None,
                 payload: Optional[Dict[str, Any]] = None) -> None:
        super().__init__(message)
        self.status = status
        self.request_id = request_id
        self.payload = payload


class OpenAIClient:
    """A tiny, dependency-free client for the OpenAI Responses API."""

    def __init__(
        self,
        api_key: [REDACTED_SECRET] = None,
        *,
        base_url: str = DEFAULT_BASE_URL,
        model: str = DEFAULT_MODEL,
        timeout: float = DEFAULT_TIMEOUT,
        organization: Optional[str] = None,
    ) -> None:
        # Prefer an explicit argument, else the environment. Never hardcode keys.
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY")
        if not self.api_key:
            raise OpenAIError(
                "No API key provided. Set the OPENAI_API_KEY environment "
                "variable or pass api_key=... to OpenAIClient."
            )
        self.base_url = base_url.rstrip("/")
        self.model = model
        self.timeout = timeout
        self.organization = organization or os.environ.get("OPENAI_ORG_ID")

    # -- public API --------------------------------------------------------

    def create_response(
        self,
        prompt: str,
        *,
        instructions: Optional[str] = None,
        model: Optional[str] = None,
        max_output_tokens: Optional[int] = None,
        temperature: Optional[float] = None,
        previous_response_id: Optional[str] = None,
        extra: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        """Send ``prompt`` and return the parsed JSON response object."""
        if not isinstance(prompt, str) or not prompt:
            raise ValueError("prompt must be a non-empty string")

        payload: Dict[str, Any] = {
            "model": model or self.model,
            "input": prompt,
        }
        if instructions is not None:
            payload["instructions"] = instructions
        if max_output_tokens is not None:
            payload["max_output_tokens"] = max_output_tokens
        if temperature is not None:
            payload["temperature"] = temperature
        if previous_response_id is not None:
            payload["previous_response_id"] = previous_response_id
        if extra:
            payload.update(extra)

        return self._post("/responses", payload)

    def ask(self, prompt: str, **kwargs: Any) -> str:
        """Send ``prompt`` and return only the assistant'"'s text output.\"\"\"
        return extract_text(self.create_response(prompt, **kwargs))

    # -- internals ---------------------------------------------------------

    def _post(self, path: str, payload: Dict[str, Any]) -> Dict[str, Any]:
        url = f\"{self.base_url}{path}\"
        body = json.dumps(payload).encode(\"utf-8\")

        headers = {
            \"Authorization\": f\"Bearer {self.api_key}\",
            \"Content-Type\": \"application/json\",
            \"Accept\": \"application/json\",
            \"User-Agent\": \"openai-client/1.0 (stdlib)\",
        }
        if self.organization:
            headers[\"OpenAI-Organization\"] = self.organization

        request = urllib.request.Request(
            url, data=body, headers=headers, method=\"POST\"
        )

        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                raw = response.read().decode(\"utf-8\")
        except urllib.error.HTTPError as exc:
            raise self._http_error(exc) from None
        except urllib.error.URLError as exc:
            raise OpenAIError(f\"Could not reach OpenAI: {exc.reason}\") from None
        except TimeoutError:
            raise OpenAIError(
                f\"Request timed out after {self.timeout} seconds.\"
            ) from None

        try:
            return json.loads(raw)
        except json.JSONDecodeError as exc:
            raise OpenAIError(\"Received a non-JSON response from OpenAI.\") from exc

    @staticmethod
    def _http_error(exc: urllib.error.HTTPError) -> OpenAIError:
        request_id = exc.headers.get(\"x-request-id\") if exc.headers else None
        payload: Optional[Dict[str, Any]] = None
        detail = \"\"
        try:
            payload = json.loads(exc.read().decode(\"utf-8\"))
            if isinstance(payload, dict):
                err = payload.get(\"error\")
                if isinstance(err, dict):
                    detail = err.get(\"message\") or \"\"
                elif isinstance(err, str):
                    detail = err
                detail = detail or payload.get(\"message\", \"\")
        except Exception:
            payload = None

        message = f\"OpenAI request failed with HTTP {exc.code}\"
        if detail:
            message += f\": {detail}\"
        if request_id:
            message += f\" (request id: {request_id})\"
        return OpenAIError(
            message, status=exc.code, request_id=request_id, payload=payload
        )


def extract_text(response: Dict[str, Any]) -> str:
    \"\"\"Pull the assistant's text out of a Responses API result.

    The API returns output as a list of items; assistant text lives in
    "'``item["content"][i]["text"]``. Refusals are returned as-is so callers see
    them rather than silently getting an empty string.
    """
    if not isinstance(response, dict):
        raise OpenAIError("Unexpected response shape from OpenAI.")

    # Some responses include a convenience field; prefer it when present.
    if isinstance(response.get("output_text"), str) and response["output_text"]:
        return response["output_text"]

    parts: List[str] = []
    for item in _as_list(response.get("output")):
        if not isinstance(item, dict) or item.get("type") != "message":
            continue
        for chunk in _as_list(item.get("content")):
            if not isinstance(chunk, dict):
                continue
            chunk_type = chunk.get("type")
            if chunk_type in ("output_text", "text") and isinstance(
                chunk.get("text"), str
            ):
                parts.append(chunk["text"])
            elif chunk_type == "refusal" and isinstance(chunk.get("refusal"), str):
                parts.append(chunk["refusal"])

    text = "".join(parts).strip()
    if not text:
        status = response.get("status")
        if status and status != "completed":
            raise OpenAIError(f"Response did not complete (status: {status}).")
        raise OpenAIError("The response contained no text output.")
    return text


def _as_list(value: Any) -> Iterable[Any]:
    if isinstance(value, list):
        return value
    return []


def ask(prompt: str, **kwargs: Any) -> str:
    """Convenience wrapper: create a client and return the text output."""
    return OpenAIClient().ask(prompt, **kwargs)


def _main(argv: List[str]) -> int:
    prompt = " ".join(argv[1:]).strip() if len(argv) > 1 else sys.stdin.read().strip()
    if not prompt:
        print("usage: python openai_client.py <prompt>", file=sys.stderr)
        return 2
    try:
        print(ask(prompt))
    except OpenAIError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(_main(sys.argv))
